// C1.3 — Ferramentas do desenvolvedor e expressões regulares: exercícios, prova final e projeto integrador.

export const exsets = {
'fer-01': [
  { id: 'fer-01-e1', type: 'mc', difficulty: 1, points: 10, prompt: 'O parâmetro §usr§ de uma função aparece em 12 arquivos e você quer chamá-lo §usuario§. Qual abordagem é a mais segura?', options: ['Busca e substituição textual de "usr" em todo o projeto', 'Renomear o símbolo (F2) com o servidor de linguagem, revisando a pré-visualização', 'Editar um arquivo por vez de memória', 'Apagar a função e reescrevê-la'], answer: 1, explanation: 'O renomear de símbolo atua sobre o significado do código (via LSP) e só altera as referências reais. A substituição textual também mudaria §usrAgent§, comentários e strings.' },
  { id: 'fer-01-e2', type: 'match', difficulty: 1, points: 10, prompt: 'Associe cada atalho de terminal ao efeito.', pairs: [['Ctrl+R', 'Busca incremental no histórico'], ['Ctrl+W', 'Apaga a palavra anterior'], ['!!', 'Repete o último comando'], ['cd -', 'Volta ao diretório anterior']], explanation: 'Esses quatro atalhos economizam muito: o histórico (§Ctrl+R§), a edição de linha (§Ctrl+W§), a repetição (§!!§, comum em §sudo !!§) e a navegação (§cd -§).' },
  { id: 'fer-01-e3', type: 'tf', difficulty: 2, points: 5, prompt: 'Uma senha passada como argumento na linha de comando fica registrada no histórico do shell e pode aparecer na lista de processos.', answer: true, explanation: 'Comandos digitados vão para o histórico (§~/.bash_history§) e os argumentos ficam visíveis em §ps§. Prefira variáveis de ambiente lidas de um arquivo protegido, entrada interativa ou gerenciadores de segredos.' },
  { id: 'fer-01-e4', type: 'fill', difficulty: 1, points: 10, prompt: 'Complete o §.editorconfig§ para que todos usem UTF-8, finais de linha LF e indentação com 2 espaços.', code: 'root = true\n\n[*]\ncharset = [[0]]\nend_of_line = [[1]]\nindent_style = space\nindent_size = [[2]]', answers: [['utf-8'], ['lf'], ['2']], explanation: 'O EditorConfig padroniza o básico entre editores. §root = true§ impede a busca em pastas acima e os valores seguem a documentação oficial.' },
  { id: 'fer-01-e5', type: 'code', difficulty: 2, points: 20, prompt: 'Implemente §parseDotenv(texto)§, que lê o conteúdo de um arquivo §.env§ e devolve um objeto. Regras: ignore linhas em branco e comentários (§#§ no início da linha); aceite o prefixo §export §; o nome deve casar com §[A-Za-z_][A-Za-z0-9_]*§; valores entre aspas duplas ou simples têm as aspas removidas (nas duplas, a sequência §\\n§ vira quebra de linha); valores sem aspas terminam em um comentário §" #..."§ (espaço e §#§), que deve ser removido e o resultado aparado. Linha sem §=§ ou com nome inválido lança §Error("linha inválida: N")§, com N a partir de 1.', lang: 'javascript', starter: 'function parseDotenv(texto) {\n  // seu código aqui\n}\n', hints: ['Divida em linhas e percorra com o índice para montar a mensagem de erro.', 'Procure o primeiro "=" com indexOf e valide o nome com uma regex.'], tests: [{ name: 'chaves, comentários, export e aspas', code: "const r = parseDotenv('A=1\\n# comentário\\n\\nB=\"x y\"\\nexport C=3 # nota');\nassert.deepEqual(r, { A: '1', B: 'x y', C: '3' });" }, { name: 'aspas simples preservam o #', code: "assert.deepEqual(parseDotenv(\"D='a#b'\"), { D: 'a#b' });" }, { name: 'sequência \\n nas aspas duplas', code: "assert.equal(parseDotenv('E=\"l1\\\\nl2\"').E, 'l1\\nl2');" }, { name: 'valor vazio e com sinal de igual', code: "assert.deepEqual(parseDotenv('F=\\nG=a=b'), { F: '', G: 'a=b' });" }, { name: 'linhas inválidas', code: "assert.throws(() => parseDotenv('semigual'), 'linha inválida: 1'); assert.throws(() => parseDotenv('A=1\\nruim'), 'linha inválida: 2'); assert.throws(() => parseDotenv('1A=2'), 'linha inválida: 1'); assert.throws(() => parseDotenv('=x'), 'linha inválida: 1');" }], solution: "function parseDotenv(texto) {\n  const out = {};\n  texto.split('\\n').forEach((bruta, i) => {\n    let l = bruta.trim();\n    if (!l || l.startsWith('#')) return;\n    if (l.startsWith('export ')) l = l.slice(7).trim();\n    const p = l.indexOf('=');\n    if (p < 1) throw new Error('linha inválida: ' + (i + 1));\n    const k = l.slice(0, p).trim();\n    if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(k)) throw new Error('linha inválida: ' + (i + 1));\n    let v = l.slice(p + 1).trim();\n    if (v.length >= 2 && v.startsWith('\"') && v.endsWith('\"')) v = v.slice(1, -1).replace(/\\\\n/g, '\\n');\n    else if (v.length >= 2 && v.startsWith(\"'\") && v.endsWith(\"'\")) v = v.slice(1, -1);\n    else { const h = v.search(/\\s#/); if (h >= 0) v = v.slice(0, h).trim(); }\n    out[k] = v;\n  });\n  return out;\n}\n", explanation: 'Arquivos de configuração simples como o §.env§ têm regras pequenas, mas cheias de casos de borda (aspas, comentários, §=§ dentro do valor). Escrever o parser mostra por que bibliotecas como o dotenv existem e por que o arquivo §.env§ nunca deve ser versionado com segredos.' }
],
'fer-02': [
  { id: 'fer-02-e1', type: 'mc', difficulty: 2, points: 10, prompt: 'Uma lista de itens só trava quando tem mais de 100 elementos, e o breakpoint na linha do laço pausa 100 vezes antes do problema. Qual recurso do DevTools resolve melhor?', options: ['Remover o breakpoint e usar alert()', 'Um breakpoint condicional (por exemplo, i === 100)', 'Recarregar a página várias vezes', 'Aumentar o zoom do navegador'], answer: 1, explanation: 'Breakpoints condicionais só pausam quando a expressão é verdadeira. Para apenas observar valores sem pausar, um logpoint é a alternativa.' },
  { id: 'fer-02-e2', type: 'trace', difficulty: 2, points: 10, prompt: 'Leia o stack trace.', code: "TypeError: Cannot read properties of undefined (reading 'nome')\n    at formatarUsuario (app.js:12:20)\n    at renderLista (app.js:30:9)\n    at HTMLButtonElement.<anonymous> (app.js:48:5)", lang: 'text', steps: [{ q: 'Qual função estourou o erro? (nome da função)', answers: ['formatarUsuario'] }, { q: 'Qual função chamou a que estourou?', answers: ['renderLista'] }, { q: 'Em qual linha do arquivo o erro ocorreu?', answers: ['12'] }], explanation: 'O primeiro quadro é onde estourou (§formatarUsuario§, linha 12); o seguinte mostra quem chamou (§renderLista§). Para achar a causa, suba a pilha e descubra quem passou o §undefined§.' },
  { id: 'fer-02-e3', type: 'tf', difficulty: 1, points: 5, prompt: 'O painel Elements mostra exatamente o HTML que o servidor enviou, sem as alterações feitas por JavaScript.', answer: false, explanation: 'O Elements mostra o **DOM vivo**: o estado atual da página, incluindo mudanças feitas por scripts. Para ver o HTML original, use "Ver código-fonte" ou a resposta no painel Network.' },
  { id: 'fer-02-e4', type: 'match', difficulty: 1, points: 10, prompt: 'Associe o objetivo à ferramenta do DevTools.', pairs: [['Ver status, cabeçalhos e tempo de uma requisição fetch', 'Network'], ['Parar o código em uma linha e inspecionar o escopo', 'Sources'], ['Alterar um estilo CSS ao vivo e ver a cascata', 'Elements'], ['Ver o conteúdo do localStorage e dos cookies', 'Application']], explanation: 'Cada painel responde a uma pergunta: rede (Network), execução (Sources), DOM e CSS (Elements) e armazenamento (Application).' },
  { id: 'fer-02-e5', type: 'code', difficulty: 3, points: 25, prompt: 'Implemente §parseStack(stack)§, que extrai os quadros de um stack trace no formato do V8. Considere apenas as linhas que começam com espaços e §at §. Cada quadro vira §{ funcao, arquivo, linha, coluna, async }§: §funcao§ é o nome (ou §null§ se o quadro for anônimo, sem parênteses); §arquivo§ é o caminho ou URL (pode conter §:§, como em §file:///a.mjs§ ou §C:\\\\app\\\\a.js§); §linha§ e §coluna§ são números; §async§ é §true§ se a linha tiver §at async §. A primeira linha (mensagem) e linhas que não casam são ignoradas.', lang: 'javascript', starter: 'function parseStack(stack) {\n  // seu código aqui\n}\n', hints: ['Duas formas: "at nome (arquivo:linha:coluna)" e "at arquivo:linha:coluna".', 'Use uma regex que lê linha e coluna sempre do FINAL da linha.'], tests: [{ name: 'quadros nomeados, anônimos e async', code: "const s = ['Error: x', '    at interna (/app/e.js:1:28)', '    at externa (/app/e.js:2:22)', '    at /app/x.js:3:9', '    at async handler (file:///a.mjs:5:1)'].join('\\n');\nassert.deepEqual(parseStack(s), [\n  { funcao: 'interna', arquivo: '/app/e.js', linha: 1, coluna: 28, async: false },\n  { funcao: 'externa', arquivo: '/app/e.js', linha: 2, coluna: 22, async: false },\n  { funcao: null, arquivo: '/app/x.js', linha: 3, coluna: 9, async: false },\n  { funcao: 'handler', arquivo: 'file:///a.mjs', linha: 5, coluna: 1, async: true }\n]);" }, { name: 'nome com ponto e <anonymous>', code: "const r = parseStack('E\\n    at Object.<anonymous> (/x/y.js:11:1)');\nassert.equal(r[0].funcao, 'Object.<anonymous>'); assert.equal(r[0].linha, 11);" }, { name: 'caminho do Windows', code: "const r = parseStack('E\\n    at f (C:\\\\app\\\\a.js:7:2)'); assert.equal(r[0].arquivo, 'C:\\\\app\\\\a.js'); assert.equal(r[0].coluna, 2);" }, { name: 'sem quadros', code: "assert.deepEqual(parseStack('Error: só a mensagem'), []); assert.deepEqual(parseStack(''), []);" }], solution: "function parseStack(stack) {\n  const quadros = [];\n  for (const l of stack.split('\\n')) {\n    const m = /^\\s+at (?:(async) )?(?:(.+?) \\((.+):(\\d+):(\\d+)\\)|(.+):(\\d+):(\\d+))$/.exec(l);\n    if (!m) continue;\n    const nomeado = m[2] !== undefined;\n    quadros.push({\n      funcao: nomeado ? m[2] : null,\n      arquivo: nomeado ? m[3] : m[6],\n      linha: Number(nomeado ? m[4] : m[7]),\n      coluna: Number(nomeado ? m[5] : m[8]),\n      async: m[1] === 'async'\n    });\n  }\n  return quadros;\n}\n", explanation: 'Ferramentas de monitoramento de erros fazem exatamente isso: transformam o texto da pilha em dados (função, arquivo, linha) para agrupar erros e mostrar o código. Ancorar a leitura de linha e coluna no final da linha resolve caminhos com dois-pontos.' },
  { id: 'fer-02-e6', type: 'open', difficulty: 2, points: 10, prompt: 'Uma tela mostra a lista vazia depois que o usuário clica em "Carregar", mas a API devolve os dados normalmente. Descreva como investigaria no navegador, citando os painéis e o que procuraria.', model: 'Reproduzir o clique. No Network, ver se a requisição foi feita, o status, o payload e se a resposta contém os dados (e se há cache). No Console, procurar erros e o stack trace. No Sources, colocar um breakpoint (ou logpoint) no código que recebe a resposta e no que atualiza o estado/DOM para ver se o valor chega e se a renderização é chamada depois; verificar a ordem de execução assíncrona. No Elements, conferir se o DOM foi atualizado (e se CSS não o esconde). Formular a hipótese e testar uma por vez.', rubric: ['Usa o Network para confirmar requisição, status e corpo', 'Verifica erros no Console e lê o stack trace', 'Usa breakpoint ou logpoint para acompanhar o valor até a renderização', 'Confere o DOM e o CSS no Elements', 'Testa uma hipótese por vez'], explanation: 'A resposta forte divide o problema em camadas (rede, dados, estado, DOM) e usa a ferramenta certa para cada uma, em vez de adivinhar.' }
],
'fer-03': [
  { id: 'fer-03-e1', type: 'mc', difficulty: 2, points: 10, prompt: 'Você quer depurar um erro que ocorre ao ler a configuração, logo no início do programa, antes de dar tempo de conectar o depurador. Qual opção usar?', options: ['node --inspect app.js', 'node --inspect-brk app.js', 'node --watch app.js', 'node --stack-trace-limit=1 app.js'], answer: 1, explanation: '§--inspect-brk§ pausa na primeira linha e espera o depurador. Com §--inspect§ puro, o programa já teria terminado de ler a configuração.' },
  { id: 'fer-03-e2', type: 'tf', difficulty: 2, points: 5, prompt: 'É seguro iniciar um servidor de produção com §--inspect=0.0.0.0:9229§, pois só quem conhece a porta consegue se conectar.', answer: false, explanation: 'O inspector permite executar código arbitrário no processo. Expô-lo à rede dá controle total a qualquer um que o alcance (portas são facilmente varridas). Mantenha em §127.0.0.1§ e use túnel SSH.' },
  { id: 'fer-03-e3', type: 'match', difficulty: 1, points: 10, prompt: 'Associe a opção do Node.js ao que ela faz.', pairs: [['--watch', 'Reinicia o programa quando os arquivos mudam'], ['--inspect-brk', 'Ativa o inspector e pausa na primeira linha'], ['--enable-source-maps', 'Faz as pilhas apontarem para o código original (TypeScript, transpilado)'], ['--stack-trace-limit=50', 'Aumenta o número de quadros mostrados na pilha']], explanation: 'São as quatro opções de dia a dia para depurar e desenvolver com Node.js moderno.' },
  { id: 'fer-03-e4', type: 'bug', difficulty: 2, points: 10, prompt: 'O código abaixo tenta tratar o erro, mas o processo termina com "Uncaught Error" quando a leitura falha. Clique na linha que impede o tratamento.', code: "const fs = require('node:fs');\ntry {\n  fs.readFile('config.json', (err, dados) => {\n    if (err) throw err;\n    console.log(dados.length);\n  });\n} catch (e) {\n  console.error('falhou:', e.message);\n}", answer: 4, explanation: 'O §throw§ dentro do callback ocorre depois, em outra pilha, fora do §try/catch§ ao redor. Trate o erro no próprio callback (§if (err) { console.error(...); return; }§) ou use a versão com promises e §await§.' },
  { id: 'fer-03-e5', type: 'code', difficulty: 3, points: 25, prompt: 'Implemente §parseFlagsNode(args)§, que interpreta os argumentos de uma linha §node ...§ (sem o §node§). Devolva §{ inspecionar, aguardar, host, porta, script, exposto }§. §--inspect§ liga o inspector; §--inspect-brk§ também liga e define §aguardar§. Ambos aceitam §=porta§, §=host§ ou §=host:porta§. Padrões: host §"127.0.0.1"§ e porta §9229§. §script§ é o primeiro argumento que **não** começa com §-§ (os seguintes pertencem ao programa e são ignorados). Outras opções (§--watch§ etc.) são ignoradas. §exposto§ é §true§ quando o host não é §127.0.0.1§, §localhost§ nem §::1§. Se não houver script, lance §Error("script ausente")§.', lang: 'javascript', starter: 'function parseFlagsNode(args) {\n  // seu código aqui\n}\n', hints: ['Use uma regex como /^--inspect(-brk)?(?:=(.+))?$/ em cada opção.', 'Para host:porta, separe no ÚLTIMO ":".'], tests: [{ name: 'padrões', code: "assert.deepEqual(parseFlagsNode(['--inspect', 'app.js']), { inspecionar: true, aguardar: false, host: '127.0.0.1', porta: 9229, script: 'app.js', exposto: false });" }, { name: 'brk com porta', code: "const r = parseFlagsNode(['--inspect-brk=9230', 'app.js']); assert.equal(r.aguardar, true); assert.equal(r.porta, 9230); assert.equal(r.host, '127.0.0.1');" }, { name: 'host e porta, exposto', code: "const r = parseFlagsNode(['--inspect=0.0.0.0:9300', 'x.js']); assert.equal(r.host, '0.0.0.0'); assert.equal(r.porta, 9300); assert.equal(r.exposto, true); assert.equal(parseFlagsNode(['--inspect=localhost:1', 'x.js']).exposto, false);" }, { name: 'sem inspector e flags depois do script', code: "const a = parseFlagsNode(['--watch', 'app.js']); assert.equal(a.inspecionar, false); assert.equal(a.script, 'app.js');\nconst b = parseFlagsNode(['app.js', '--inspect']); assert.equal(b.inspecionar, false); assert.equal(b.script, 'app.js');" }, { name: 'sem script', code: "assert.throws(() => parseFlagsNode([]), 'script ausente'); assert.throws(() => parseFlagsNode(['--inspect']), 'script ausente');" }], solution: "function parseFlagsNode(args) {\n  const r = { inspecionar: false, aguardar: false, host: '127.0.0.1', porta: 9229, script: null, exposto: false };\n  for (const a of args) {\n    if (!a.startsWith('-')) { r.script = a; break; }\n    const m = /^--inspect(-brk)?(?:=(.+))?$/.exec(a);\n    if (!m) continue;\n    r.inspecionar = true;\n    r.aguardar = !!m[1];\n    if (m[2]) {\n      const v = m[2];\n      if (v.includes(':')) { const i = v.lastIndexOf(':'); r.host = v.slice(0, i); r.porta = Number(v.slice(i + 1)); }\n      else if (/^\\d+$/.test(v)) r.porta = Number(v);\n      else r.host = v;\n    }\n  }\n  if (!r.script) throw new Error('script ausente');\n  r.exposto = !['127.0.0.1', 'localhost', '::1'].includes(r.host);\n  return r;\n}\n", explanation: 'Os argumentos depois do script são do programa, não do Node; é um erro comum colocar §--inspect§ no lugar errado. A propriedade §exposto§ lembra o risco de segurança: o inspector fora do loopback permite execução remota de código.' },
  { id: 'fer-03-e6', type: 'open', difficulty: 2, points: 10, prompt: 'Sua API em Node.js, em um contêiner na nuvem, está com comportamento estranho e você precisa depurá-la. Descreva uma forma segura de conectar o depurador e o que evitaria.', model: 'Ativar o inspector só de forma pontual (por exemplo, sinal SIGUSR1 ou reiniciar com --inspect em um ambiente de teste), mantendo-o em 127.0.0.1 dentro do contêiner; mapear a porta somente para o loopback do host e acessar por túnel SSH (ssh -L 9229:127.0.0.1:9229) ou kubectl port-forward; conectar pelo VS Code (attach) ou chrome://inspect; evitar expor a porta 9229 publicamente ou usar 0.0.0.0, deixar o inspector ligado em produção por padrão e depurar com tráfego real sem controle; preferir reproduzir em ambiente de homologação e usar logs estruturados.', rubric: ['Mantém o inspector em 127.0.0.1 e acessa por túnel (SSH ou port-forward)', 'Ativa de forma pontual e controlada, não permanente', 'Evita expor a porta publicamente ou usar 0.0.0.0', 'Considera reproduzir em ambiente não produtivo e usar logs'], explanation: 'O inspector é uma porta de execução de código; trate-a com o mesmo cuidado de um acesso SSH.' }
],
'fer-04': [
  { id: 'fer-04-e1', type: 'match', difficulty: 1, points: 10, prompt: 'Associe a ferramenta à sua função.', pairs: [['Prettier', 'Reescreve o código em um estilo padrão (formatador)'], ['ESLint', 'Encontra padrões suspeitos como variáveis não usadas e == (linter)'], ['TypeScript (tsc)', 'Verifica a coerência dos tipos'], ['EditorConfig', 'Padroniza indentação, codificação e finais de linha entre editores']], explanation: 'São camadas complementares: nenhuma substitui a outra.' },
  { id: 'fer-04-e2', type: 'mc', difficulty: 2, points: 10, prompt: 'No ESLint, o que significa configurar uma regra com a severidade §"warn"§?', options: ['A regra está desativada', 'A regra reporta o problema, mas não faz o comando falhar (a menos que se use --max-warnings 0)', 'A regra corrige o código automaticamente', 'A regra só vale para arquivos de teste'], answer: 1, explanation: '§"off"§ desativa, §"warn"§ avisa sem falhar e §"error"§ faz o ESLint sair com código 1. Para tornar avisos bloqueantes no CI, use §--max-warnings 0§.' },
  { id: 'fer-04-e3', type: 'bug', difficulty: 2, points: 10, prompt: 'A configuração do ESLint abaixo deveria ignorar a pasta §dist§ e exigir §===§, mas todos os arquivos de §dist§ continuam sendo analisados. Clique na linha com o problema.', code: 'import js from "@eslint/js";\n\nexport default [\n  js.configs.recommended,\n  { rules: { eqeqeq: "error" } },\n  { ignore: ["dist/**"] },\n];', answer: 6, explanation: 'Na configuração plana, a propriedade correta é §ignores§ (no plural), em um objeto sozinho. Com §ignore§, a chave é ignorada silenciosamente e nada é excluído.' },
  { id: 'fer-04-e4', type: 'tf', difficulty: 2, points: 5, prompt: 'A opção §eslint --fix§ corrige automaticamente todos os problemas reportados, incluindo o uso de §==§ onde §===§ seria o correto.', answer: false, explanation: 'O §--fix§ aplica apenas correções seguras (por exemplo, trocar §var§ por §const§ quando possível). Trocar §==§ por §===§ pode mudar o comportamento e exige decisão humana, por isso fica sem correção automática.' },
  { id: 'fer-04-e5', type: 'code', difficulty: 2, points: 20, prompt: 'Implemente §lintSimples(codigo)§, um minilinter. Para cada linha (numeradas a partir de 1), produza itens §{ linha, regra }§ nesta ordem: §"no-var"§ se a linha contém a palavra §var§ seguida de espaço; §"eqeqeq"§ se contém §==§ ou §!=§ que **não** façam parte de §===§, §!==§, §<=§, §>=§; §"no-console"§ se contém §console.§. Linhas cujo primeiro texto (sem espaços) começa com §//§ são ignoradas.', lang: 'javascript', starter: 'function lintSimples(codigo) {\n  // seu código aqui\n}\n', hints: ['Percorra as linhas com índice; use regex por regra.', 'Para o == isolado: /(?:^|[^=!<>])(?:==|!=)(?!=)/.'], tests: [{ name: 'no-var', code: "assert.deepEqual(lintSimples('var a = 1;'), [{ linha: 1, regra: 'no-var' }]);" }, { name: 'eqeqeq: == e != são ruins; === e !== são bons', code: "assert.deepEqual(lintSimples('if (a == b) {}'), [{ linha: 1, regra: 'eqeqeq' }]); assert.deepEqual(lintSimples('if (a != b) {}'), [{ linha: 1, regra: 'eqeqeq' }]); assert.deepEqual(lintSimples('if (a === b || c !== d) {}'), []); assert.deepEqual(lintSimples('if (x >= 1 && y <= 2) {}'), []);" }, { name: 'no-console', code: "assert.deepEqual(lintSimples('console.log(1)'), [{ linha: 1, regra: 'no-console' }]);" }, { name: 'comentários ignorados e numeração', code: "const c = 'let ok = 1;\\n  // var x == 1\\nvar y = 2; if (y == 2) console.log(y);';\nassert.deepEqual(lintSimples(c), [{ linha: 3, regra: 'no-var' }, { linha: 3, regra: 'eqeqeq' }, { linha: 3, regra: 'no-console' }]);" }, { name: 'palavra parecida com var', code: "assert.deepEqual(lintSimples('const variavel = 1;'), []);" }], solution: "function lintSimples(codigo) {\n  const achados = [];\n  codigo.split('\\n').forEach((l, i) => {\n    if (l.trim().startsWith('//')) return;\n    if (/\\bvar\\s/.test(l)) achados.push({ linha: i + 1, regra: 'no-var' });\n    if (/(?:^|[^=!<>])(?:==|!=)(?!=)/.test(l)) achados.push({ linha: i + 1, regra: 'eqeqeq' });\n    if (/\\bconsole\\./.test(l)) achados.push({ linha: i + 1, regra: 'no-console' });\n  });\n  return achados;\n}\n", explanation: 'Linters reais analisam a árvore sintática, não o texto; por isso não confundem um §var§ dentro de uma string. Este exercício mostra a ideia (regras pequenas, mensagens com posição) e, de quebra, a precisão que o §==§ exige em regex.' },
  { id: 'fer-04-e6', type: 'open', difficulty: 2, points: 10, prompt: 'Você entrou em um projeto com 300 arquivos sem formatação padronizada e quer adotar o Prettier sem atrapalhar o trabalho do time nem o histórico. Descreva seu plano.', model: 'Alinhar com o time; adicionar Prettier e configuração mínima (versão fixa, .prettierrc, .prettierignore); rodar prettier --write em um commit separado, sem mudanças de lógica, em um momento com poucos PRs abertos; registrar o hash em .git-blame-ignore-revs e configurar blame.ignoreRevsFile; adicionar prettier --check ao CI e um script npm; configurar o editor para formatar ao salvar; opcionalmente, pre-commit com lint-staged; comunicar o commit para quem tem branches abertas (rebase/reformat).', rubric: ['Faz a formatação em um commit isolado sem mudanças de lógica', 'Registra o commit em .git-blame-ignore-revs', 'Adiciona verificação no CI (--check) e fixa a versão da ferramenta', 'Combina com o time e prepara quem tem branches abertas'], explanation: 'O objetivo é adotar a ferramenta com o menor atrito e sem perder a rastreabilidade do git blame.' }
],
'fer-05': [
  { id: 'fer-05-e1', type: 'mc', difficulty: 1, points: 10, prompt: 'Como passar a opção §--fix§ ao ESLint usando o script §"lint": "eslint src"§ do package.json?', options: ['npm run lint --fix', 'npm run lint -- --fix', 'npm lint --fix', 'npm run --fix lint'], answer: 1, explanation: 'O §--§ separa as opções do próprio npm das que devem ser repassadas ao comando do script. Sem ele, o npm pode interpretar a opção por conta própria.' },
  { id: 'fer-05-e2', type: 'tf', difficulty: 2, points: 5, prompt: 'Os hooks guardados em §.git/hooks§ são versionados e chegam a todas as pessoas quando elas clonam o repositório.', answer: false, explanation: 'O diretório §.git§ não é versionado. Para compartilhar hooks, guarde-os em uma pasta do repositório e use §git config core.hooksPath§ (ou ferramentas como Husky) e automatize com um script §prepare§.' },
  { id: 'fer-05-e3', type: 'fill', difficulty: 2, points: 10, prompt: 'Complete a configuração de hooks versionados e a listagem dos arquivos em staging.', code: 'git config [[0]] .githooks\ngit diff --cached --name-only --diff-filter=[[1]]', answers: [['core.hooksPath'], ['ACM']], explanation: '§core.hooksPath§ aponta o Git para a pasta de hooks do repositório. §--diff-filter=ACM§ lista arquivos adicionados, copiados e modificados em staging, a entrada típica do lint-staged.' },
  { id: 'fer-05-e4', type: 'mc', difficulty: 3, points: 10, prompt: 'Alguém contorna o §pre-commit§ com §git commit --no-verify§ e envia código com erros de lint. Qual a medida que realmente garante a qualidade?', options: ['Proibir o uso de --no-verify por regra escrita no README', 'Repetir as verificações no CI e proteger a branch principal (merge só com CI verde)', 'Remover o hook para evitar que o problema aconteça', 'Rodar o lint apenas no computador de quem faz a revisão'], answer: 1, explanation: 'Hooks locais são conveniência e podem ser pulados ou não instalados. O CI é a barreira obrigatória; a proteção de branch impede o merge sem as verificações.' },
  { id: 'fer-05-e5', type: 'code', difficulty: 2, points: 20, prompt: 'Implemente §planejarLintStaged(arquivos, config)§. §arquivos§ é a lista de caminhos em staging. §config§ é um array de §{ ext, cmd }§, em que §ext§ é uma lista de extensões (com ponto, ex.: §".js"§). Devolva um array de §{ cmd, arquivos }§, **na ordem de §config§**, só para os comandos que tenham ao menos um arquivo correspondente; um arquivo pode entrar em vários comandos; a ordem dos arquivos é a original. A extensão é o trecho a partir do **último ponto** do nome do arquivo (sem diferenciar maiúsculas); arquivos sem extensão (inclusive os que só têm o ponto inicial, como §.prettierrc§) não casam.', lang: 'javascript', starter: 'function planejarLintStaged(arquivos, config) {\n  // seu código aqui\n}\n', hints: ['Pegue o nome base com split("/").pop().', 'lastIndexOf(".") > 0 indica que há extensão.'], tests: [{ name: 'agrupa por comando e mantém a ordem', code: "const cfg = [{ ext: ['.js', '.ts'], cmd: 'eslint --fix' }, { ext: ['.js', '.md', '.json'], cmd: 'prettier --write' }];\nassert.deepEqual(planejarLintStaged(['src/a.js', 'README.md', 'src/b.ts', 'dados.json'], cfg), [{ cmd: 'eslint --fix', arquivos: ['src/a.js', 'src/b.ts'] }, { cmd: 'prettier --write', arquivos: ['src/a.js', 'README.md', 'dados.json'] }]);" }, { name: 'comando sem arquivos é omitido', code: "assert.deepEqual(planejarLintStaged(['a.md'], [{ ext: ['.js'], cmd: 'x' }]), []);" }, { name: 'extensão sem diferenciar maiúsculas e último ponto', code: "const r = planejarLintStaged(['App.JS', 'x.test.js'], [{ ext: ['.js'], cmd: 'e' }]); assert.deepEqual(r[0].arquivos, ['App.JS', 'x.test.js']);" }, { name: 'sem extensão e dotfiles não casam', code: "assert.deepEqual(planejarLintStaged(['Makefile', '.prettierrc', 'src/.env'], [{ ext: ['.prettierrc', '.env', ''], cmd: 'x' }]), []);" }, { name: 'lista vazia', code: "assert.deepEqual(planejarLintStaged([], [{ ext: ['.js'], cmd: 'x' }]), []);" }], solution: "function planejarLintStaged(arquivos, config) {\n  const extDe = (f) => {\n    const base = f.split('/').pop();\n    const i = base.lastIndexOf('.');\n    return i > 0 ? base.slice(i).toLowerCase() : null;\n  };\n  const plano = [];\n  for (const { ext, cmd } of config) {\n    const alvo = ext.map((e) => e.toLowerCase());\n    const lista = arquivos.filter((f) => { const e = extDe(f); return e !== null && alvo.includes(e); });\n    if (lista.length) plano.push({ cmd, arquivos: lista });\n  }\n  return plano;\n}\n", explanation: 'É a lógica central do lint-staged: agrupar os arquivos em staging por tipo e rodar o comando certo em cada grupo. Rodar só no que mudou mantém o hook rápido.' },
  { id: 'fer-05-e6', type: 'open', difficulty: 2, points: 10, prompt: 'Proponha o conjunto de verificações para o editor, o hook pre-commit, o pre-push e o CI de um projeto Node.js, justificando o que vai em cada etapa.', model: 'Editor: formatação ao salvar e lint em tempo real. Pre-commit: lint e Prettier apenas nos arquivos em staging (rápido, poucos segundos). Pre-push (opcional): testes rápidos. CI: npm ci, npm run check (eslint --max-warnings 0, prettier --check), testes completos e eventualmente build; é obrigatório e protege a branch principal. Justificativa: feedback imediato onde é barato, verificações completas onde há garantia e tempo.', rubric: ['Pre-commit rápido, só em arquivos em staging', 'Testes mais lentos no pre-push ou CI', 'CI repete as verificações e é obrigatório', 'Menciona formatação e lint no editor'], explanation: 'A ideia é dar feedback cedo (editor e hook), mas confiar no CI como barreira final.' }
],
'fer-06': [
  { id: 'fer-06-e1', type: 'mc', difficulty: 1, points: 10, prompt: 'Qual regex casa exatamente o texto §3.14§ (e não §3x14§)?', options: ['/3.14/', '/3\\.14/', '/3[.]*14/', '/3\\d14/'], answer: 1, explanation: 'O ponto sem escape casa qualquer caractere. Com §\\.§ (ou §[.]§) casa apenas o ponto literal. A primeira opção também aceitaria "3x14".' },
  { id: 'fer-06-e2', type: 'trace', difficulty: 2, points: 10, prompt: 'Rastreie o código.', code: "const t = '<b>a</b><b>b</b>';\nconsole.log(t.match(/<b>.*<\\/b>/)[0].length);\nconsole.log(t.match(/<b>.*?<\\/b>/)[0]);\nconsole.log('a1b22'.match(/\\d+/g).join('-'));", lang: 'javascript', steps: [{ q: 'O que a segunda linha imprime (quantidade de caracteres do casamento guloso)?', answers: ['16'] }, { q: 'O que a terceira linha imprime (casamento preguiçoso)?', answers: ['<b>a</b>'] }, { q: 'O que a quarta linha imprime?', answers: ['1-22'] }], explanation: 'O guloso (§.*§) consome até o último §</b>§, ficando com a string inteira de 16 caracteres. O preguiçoso (§.*?§) para no primeiro §</b>§. §\\d+§ com a flag §g§ devolve "1" e "22".' },
  { id: 'fer-06-e3', type: 'bug', difficulty: 2, points: 10, prompt: 'Esta função deveria dizer, para cada texto, se contém um dígito, mas devolve resultados alternados para os mesmos textos. Clique na linha com o problema.', code: 'const temDigito = /\\d/g;\nfunction contem(texto) {\n  return temDigito.test(texto);\n}\nconsole.log(contem("a1"), contem("a1"));', answer: 1, explanation: 'A flag §g§ faz a regex guardar o §lastIndex§; a segunda chamada continua de onde a primeira parou e falha. Para validar, use uma regex sem §g§ (§/\\d/§).' },
  { id: 'fer-06-e4', type: 'tf', difficulty: 2, points: 5, prompt: 'O atalho §\\w§ casa letras acentuadas como "ç" e "é".', answer: false, explanation: '§\\w§ equivale a §[A-Za-z0-9_]§. Para letras acentuadas, use §\\p{L}§ com a flag §u§.' },
  { id: 'fer-06-e5', type: 'code', difficulty: 2, points: 20, prompt: 'Implemente §ehPlaca(texto)§, que devolve §true§ se o texto é uma placa de veículo brasileira em um dos formatos: antigo §ABC-1234§ (três letras maiúsculas, hífen, quatro dígitos) ou Mercosul §ABC1D23§ (três letras maiúsculas, um dígito, uma letra maiúscula, dois dígitos). O texto deve casar **inteiro** (sem espaços ou quebras de linha extras).', lang: 'javascript', starter: 'function ehPlaca(texto) {\n  // seu código aqui\n  return false;\n}\n', hints: ['Use âncoras ^ e $ e duas alternativas dentro de um grupo sem captura.', 'Classe de letras maiúsculas: [A-Z].'], tests: [{ name: 'formatos válidos', code: "assert.equal(ehPlaca('ABC-1234'), true); assert.equal(ehPlaca('ABC1D23'), true); assert.equal(ehPlaca('XYZ9A00'), true);" }, { name: 'minúsculas e sem hífen no formato antigo', code: "assert.equal(ehPlaca('abc-1234'), false); assert.equal(ehPlaca('ABC1234'), false);" }, { name: 'tamanhos errados', code: "assert.equal(ehPlaca('ABC-123'), false); assert.equal(ehPlaca('ABCD123'), false); assert.equal(ehPlaca('AB-1234'), false); assert.equal(ehPlaca('ABC1D234'), false);" }, { name: 'texto com lixo ao redor', code: "assert.equal(ehPlaca(' ABC-1234'), false); assert.equal(ehPlaca('ABC-1234 '), false); assert.equal(ehPlaca('ABC-1234\\n'), false); assert.equal(ehPlaca('placa ABC-1234'), false);" }, { name: 'vazio', code: "assert.equal(ehPlaca(''), false);" }], solution: "function ehPlaca(texto) {\n  return /^(?:[A-Z]{3}-\\d{4}|[A-Z]{3}\\d[A-Z]\\d{2})$/.test(texto);\n}\n", explanation: 'A regex valida o **formato**; não diz se a placa existe. Sem as âncoras, "placa ABC-1234" também passaria. Em JavaScript, o §$§ sem a flag §m§ não casa antes de uma quebra de linha final, o que torna a validação mais estrita que em outras linguagens.' },
  { id: 'fer-06-e6', type: 'open', difficulty: 2, points: 10, prompt: 'Um colega propõe validar o cadastro de e-mail com uma regex enorme que "cobre o RFC inteiro". Qual a sua recomendação e por quê?', model: 'Evitar: o padrão completo é enorme, difícil de manter e ainda assim não garante que o endereço exista ou que a pessoa seja a dona. Usar uma checagem simples de formato (algo antes e depois de um @ e um domínio com ponto, sem espaços) para pegar erros de digitação e confirmar enviando um e-mail com link de verificação. Limitar o tamanho da entrada e tratar a regex como filtro, não como prova de validade.', rubric: ['Desaconselha a regex gigante e justifica (manutenção, falsos positivos/negativos)', 'Propõe checagem simples de formato', 'Propõe confirmação por e-mail como validação real', 'Menciona limite de tamanho ou riscos de desempenho'], explanation: 'A validade de um e-mail só se prova entregando algo a ele; a regex serve para evitar erros óbvios de digitação.' }
],
'fer-07': [
  { id: 'fer-07-e1', type: 'mc', difficulty: 2, points: 10, prompt: 'Qual substituição converte §18/11/2026§ em §2026-11-18§?', options: ['texto.replace(/(\\d+)\\/(\\d+)\\/(\\d+)/, "$1-$2-$3")', 'texto.replace(/(\\d{2})\\/(\\d{2})\\/(\\d{4})/, "$3-$2-$1")', 'texto.replace(/\\d{2}\\/\\d{2}\\/\\d{4}/, "$3-$2-$1")', 'texto.replace(/(\\d{4})\\/(\\d{2})\\/(\\d{2})/, "$1-$2-$3")'], answer: 1, explanation: 'É preciso capturar dia, mês e ano (§$1§, §$2§, §$3§) e reordená-los: §$3-$2-$1§. A terceira opção não tem grupos; as outras não reordenam ou esperam o ano primeiro.' },
  { id: 'fer-07-e2', type: 'match', difficulty: 2, points: 10, prompt: 'Associe a sintaxe ao seu significado.', pairs: [['(?:...)', 'Grupo sem captura'], ['(?<nome>...)', 'Grupo nomeado, acessível em match.groups'], ['(?=...)', 'Lookahead positivo: o que vem a seguir deve casar'], ['(?<!...)', 'Lookbehind negativo: o que vem antes não pode casar']], explanation: 'Grupos estruturam e capturam; lookarounds testam o contexto sem consumir texto.' },
  { id: 'fer-07-e3', type: 'trace', difficulty: 3, points: 10, prompt: 'Rastreie.', code: "const t = 'R$10 e US$20';\nconsole.log(t.match(/(?<=R\\$)\\d+/g).join());\nconsole.log(/^(?=.*\\d)(?=.*[A-Z]).{6,}$/.test('abcd1'));\nconsole.log('o o casa'.match(/\\b(\\w+) \\1\\b/)[0]);", lang: 'javascript', steps: [{ q: 'O que a segunda linha imprime?', answers: ['10'] }, { q: 'O que a terceira linha imprime (true ou false)?', answers: ['false'] }, { q: 'O que a quarta linha imprime?', answers: ['o o'] }], explanation: 'O lookbehind só aceita o número que vem depois de "R$", por isso "20" fica de fora. A terceira falha: "abcd1" tem 5 caracteres e nenhuma maiúscula. O retrovisor §\\1§ casa a segunda ocorrência da mesma palavra: "o o".' },
  { id: 'fer-07-e4', type: 'tf', difficulty: 2, points: 5, prompt: 'Sem as âncoras §^§ e §$§, a regex §/\\d{4}/§ aceita "abc1234xyz" como um número de quatro dígitos válido.', answer: true, explanation: 'Sem âncoras, a regex casa em qualquer parte do texto. Para validar o texto inteiro, use §/^\\d{4}$/§.' },
  { id: 'fer-07-e5', type: 'code', difficulty: 3, points: 25, prompt: 'Implemente §converterDatas(texto)§, que troca as datas §dd/mm/aaaa§ por §aaaa-mm-dd§ em um texto. Só converta se o dia estiver entre §01§ e §31§, o mês entre §01§ e §12§ e o ano tiver quatro dígitos; a data não pode estar colada a outras letras ou dígitos (use fronteiras de palavra). Não valide se o dia existe no mês (o formato basta).', lang: 'javascript', starter: 'function converterDatas(texto) {\n  // seu código aqui\n}\n', hints: ['Uma regex com três grupos, dia (0[1-9]|[12]\\d|3[01]), mês (0[1-9]|1[0-2]) e ano (\\d{4}).', 'Use \\b nas pontas e "$3-$2-$1" na substituição.'], tests: [{ name: 'converte várias datas', code: "assert.equal(converterDatas('18/11/2026 e 01/02/2025'), '2026-11-18 e 2025-02-01');" }, { name: 'dia ou mês fora da faixa não converte', code: "assert.equal(converterDatas('32/01/2026'), '32/01/2026'); assert.equal(converterDatas('10/13/2026'), '10/13/2026'); assert.equal(converterDatas('00/10/2026'), '00/10/2026');" }, { name: 'sem fronteira de palavra não converte', code: "assert.equal(converterDatas('v18/11/2026'), 'v18/11/2026'); assert.equal(converterDatas('18/11/20261'), '18/11/20261');" }, { name: 'texto sem datas e formato ISO', code: "assert.equal(converterDatas('nada aqui'), 'nada aqui'); assert.equal(converterDatas('2026-11-18'), '2026-11-18');" }, { name: 'dentro de frase', code: "assert.equal(converterDatas('Venceu em 05/03/2024.'), 'Venceu em 2024-03-05.');" }], solution: "function converterDatas(texto) {\n  return texto.replace(/\\b(0[1-9]|[12]\\d|3[01])\\/(0[1-9]|1[0-2])\\/(\\d{4})\\b/g, '$3-$2-$1');\n}\n", explanation: 'O padrão valida o formato; o código separado deveria validar o significado (31/02 passaria). Os grupos permitem reordenar os pedaços em uma só passagem, e §\\b§ evita converter pedaços de textos maiores.' },
  { id: 'fer-07-e6', type: 'code', difficulty: 2, points: 20, prompt: 'Implemente §senhaForte(senha)§, que devolve §true§ se a senha tem **no mínimo 10 caracteres**, ao menos uma minúscula, uma maiúscula, um dígito e um símbolo dentre §!@#$%&*§, e **nenhum espaço em branco**. Use lookaheads.', lang: 'javascript', starter: 'function senhaForte(senha) {\n  // seu código aqui\n  return false;\n}\n', hints: ['Um lookahead para cada exigência: (?=.*[a-z]), (?=.*[A-Z]) ...', 'Para proibir espaços e exigir o tamanho: \\S{10,} entre as âncoras.'], tests: [{ name: 'senha válida', code: "assert.equal(senhaForte('Abcdef12!x'), true); assert.equal(senhaForte('Zz9*zzzzzzzz'), true);" }, { name: 'faltam requisitos', code: "assert.equal(senhaForte('abcdef12!x'), false); assert.equal(senhaForte('ABCDEF12!X'), false); assert.equal(senhaForte('Abcdefgh!x'), false); assert.equal(senhaForte('Abcdef123x'), false);" }, { name: 'curta demais', code: "assert.equal(senhaForte('Ab1!xyzab'), false);" }, { name: 'espaço não é permitido', code: "assert.equal(senhaForte('Abcd ef12!x'), false);" }], solution: "function senhaForte(senha) {\n  return /^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d)(?=.*[!@#$%&*])\\S{10,}$/.test(senha);\n}\n", explanation: 'Cada lookahead olha o texto inteiro a partir do início sem consumi-lo, de modo que as condições se somam. Na prática, políticas modernas privilegiam o comprimento e a verificação contra senhas vazadas a regras rígidas de composição.' }
],
'fer-08': [
  { id: 'fer-08-e1', type: 'mc', difficulty: 2, points: 10, prompt: 'Qual dos padrões abaixo é o mais suscetível a backtracking catastrófico quando a entrada é §"aaaa…a!"§?', options: ['/^a+$/', '/^(a+)+$/', '/^[a-z]{1,50}$/', '/^a*b?$/'], answer: 1, explanation: 'Quantificadores aninhados (§(a+)+§) permitem inúmeras formas de repartir os "a", e a falha no fim obriga o motor a tentar todas. Os demais não são ambíguos dessa forma.' },
  { id: 'fer-08-e2', type: 'tf', difficulty: 2, points: 5, prompt: 'Em um servidor Node.js, uma regex que demora muito para uma entrada maliciosa só atrasa a requisição de quem a enviou.', answer: false, explanation: 'O JavaScript roda em uma única thread: enquanto a regex calcula, nenhuma outra requisição é atendida. Esse é o impacto do ReDoS.' },
  { id: 'fer-08-e3', type: 'match', difficulty: 2, points: 10, prompt: 'Associe a medida de mitigação ao seu efeito.', pairs: [['Limitar o tamanho da entrada antes da regex', 'Limita o custo mesmo de padrões ruins'], ['Reescrever sem quantificadores aninhados', 'Elimina a ambiguidade que causa a explosão'], ['Motor de tempo linear (RE2)', 'Garante tempo proporcional à entrada, sem retrovisores'], ['Executar em worker com timeout', 'Impede que um caso patológico congele o processo principal']], explanation: 'A defesa é em camadas: padrão correto, limites de entrada, motor apropriado e isolamento.' },
  { id: 'fer-08-e4', type: 'bug', difficulty: 3, points: 10, prompt: 'Uma API valida o campo "nome completo" com a regex abaixo. Um atacante envia 40 letras seguidas de "!" e o servidor trava. Clique na linha que contém o padrão vulnerável.', code: 'function validarNome(n) {\n  if (typeof n !== "string") return false;\n  return /^([a-zA-Z]+\\s?)+$/.test(n);\n}', answer: 3, explanation: '§([a-zA-Z]+\\s?)+§ é ambíguo: o espaço opcional permite repartir uma sequência de letras de inúmeras formas. Correções: §/^[a-zA-Z]+(?:\\s[a-zA-Z]+)*$/§ (espaço obrigatório entre palavras) e um limite de tamanho antes do teste.' },
  { id: 'fer-08-e5', type: 'code', difficulty: 3, points: 25, prompt: 'Implemente §regexSegura()§, que devolve uma §RegExp§ **equivalente** a §/^(a+)+$/§ (aceita exatamente as cadeias formadas por uma ou mais letras "a"), mas **sem backtracking catastrófico**. O teste usa uma entrada de 40 letras "a" seguida de "b": a regex vulnerável levaria minutos; a sua precisa responder em menos de 200 ms.', lang: 'javascript', starter: 'function regexSegura() {\n  // devolva uma RegExp\n  return /^$/;\n}\n', hints: ['Pergunte: que cadeias /^(a+)+$/ realmente aceita? A resposta é mais simples do que o padrão.', 'Sem grupo, sem aninhamento.'], tests: [{ name: 'aceita uma ou mais letras a', code: "const r = regexSegura(); assert.equal(r.test('a'), true); assert.equal(r.test('aaaa'), true);" }, { name: 'rejeita vazio e outros caracteres', code: "const r = regexSegura(); assert.equal(r.test(''), false); assert.equal(r.test('b'), false); assert.equal(r.test('aab'), false); assert.equal(r.test('baa'), false);" }, { name: 'não depende de lastIndex (sem flag g)', code: "const r = regexSegura(); assert.equal(r.test('aa'), true); assert.equal(r.test('aa'), true); assert.equal(r.global, false);" }, { name: 'entrada adversária responde rápido', code: "const r = regexSegura(); const t0 = Date.now(); const ok = r.test('a'.repeat(40) + 'b'); const ms = Date.now() - t0; assert.equal(ok, false); assert.ok(ms < 200, 'demorou ' + ms + ' ms');" }, { name: 'entrada muito longa', code: "const r = regexSegura(); const t0 = Date.now(); assert.equal(r.test('a'.repeat(100000) + 'b'), false); assert.ok(Date.now() - t0 < 500);" }], solution: "function regexSegura() {\n  return /^a+$/;\n}\n", explanation: 'Muitas vezes o padrão vulnerável nasceu de uma complicação desnecessária: aceitar "uma ou mais repetições de uma ou mais letras a" é o mesmo que aceitar "uma ou mais letras a". Simplificar elimina a ambiguidade. Caso um aluno deixe a regex vulnerável, o laboratório interrompe a execução por tempo.' },
  { id: 'fer-08-e6', type: 'code', difficulty: 2, points: 20, prompt: 'Implemente §escaparRegex(texto)§, que escapa os metacaracteres de regex de um texto (§. * + ? ^ $ { } ( ) | [ ] \\\\§) colocando uma barra invertida antes de cada um, para que §new RegExp(escaparRegex(texto))§ case exatamente com o texto literal.', lang: 'javascript', starter: 'function escaparRegex(texto) {\n  // seu código aqui\n}\n', hints: ['Use replace com uma regex que casa qualquer metacaractere e o texto de substituição "\\\\$&".'], tests: [{ name: 'ponto e parênteses', code: "assert.equal(escaparRegex('a.b'), 'a\\\\.b'); assert.equal(escaparRegex('(1+1)'), '\\\\(1\\\\+1\\\\)');" }, { name: 'texto sem metacaracteres', code: "assert.equal(escaparRegex('abc 123'), 'abc 123');" }, { name: 'casa o texto literal e só ele', code: "const t = 'a.b*c[1]'; const re = new RegExp('^' + escaparRegex(t) + '$'); assert.equal(re.test(t), true); assert.equal(re.test('axb*c[1]'), false);" }, { name: 'barra invertida, chaves e cifrão', code: "const t = 'C:\\\\dir {x} $1'; const re = new RegExp('^' + escaparRegex(t) + '$'); assert.equal(re.test(t), true);" }], solution: "function escaparRegex(texto) {\n  return texto.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');\n}\n", explanation: 'Montar regex com texto do usuário sem escapar é um erro comum: o texto vira padrão (e pode virar um ataque). Escapar os metacaracteres faz o texto ser tratado como literal.' }
]
};

